-- C18 marine serial-prefix reference and official Cat parts compatibility evidence.
-- These are catalog references, not serial/arrangement-level fitment approvals.
create table if not exists public.cat_marine_engine_serial_prefixes (
  id bigint generated by default as identity primary key,
  model_key text not null, model_name text not null, serial_prefix text not null,
  application_group text not null, application_type text not null default 'MARINE',
  source_name text not null, source_url text not null, source_note text,
  evidence_status text not null default 'REFERENCE_ONLY', captured_at timestamptz not null default now(),
  constraint cat_marine_engine_serial_prefixes_unique unique(model_key,serial_prefix,application_group),
  constraint cat_marine_engine_serial_prefixes_type_check check(application_type in ('MARINE','LAND','BOTH','UNVERIFIED')),
  constraint cat_marine_engine_serial_prefixes_status_check check(evidence_status in ('REFERENCE_ONLY','OEM_VERIFIED'))
);
alter table public.cat_marine_engine_serial_prefixes enable row level security;
on conflict(model_key,serial_prefix,application_group) do update set model_name=excluded.model_name,source_name=excluded.source_name,source_url=excluded.source_url,source_note=excluded.source_note,evidence_status='REFERENCE_ONLY',captured_at=now();

update public.part_catalog set verification_status='REFERENCE',application_type='MARINE',engine_models=ARRAY['C18']::text[],compatible_models=ARRAY['C18','C18 MARINE']::text[],source_name='Cat Parts Store',source_accessed_at=now(),application_evidence='Cat Parts Store Compatible Models explicitly lists C18 under MARINE ENGINE. This is model-family evidence only; serial prefix and arrangement fitment still require Cat SIS.',application_source_url=source_url,source_note=coalesce(source_note,'') || ' Cat Parts Store lists C18 under MARINE ENGINE; serial-number and arrangement confirmation remains required.',updated_at=now() where part_number in ('20R-7175','524-3160','226-1191','361-5093','448-4451');

on conflict(part_number) do update set name=excluded.name,description=excluded.description,technical_group=excluded.technical_group,source_name=excluded.source_name,source_url=excluded.source_url,source_note=excluded.source_note,verification_status='REFERENCE',engine_models=excluded.engine_models,compatible_models=excluded.compatible_models,application_type='MARINE',application_evidence=excluded.application_evidence,application_source_url=excluded.application_source_url,specifications=public.part_catalog.specifications || excluded.specifications,source_accessed_at=now(),updated_at=now();